        "notes": "为验证爱因斯坦相对论重力红移效应而建的太阳天文望远镜观测塔。如同一座从大地破土而出的流线型火山雕塑，圆润光滑的曲面消解了所有的传统折角，被爱因斯坦赞誉为'有机体（Organic）'。",
